arguments.file_text:
namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
    public int RatingCount => Ratings.Count;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone if available.",
                    "Stretch the dough into a 12-inch round on a floured surface.",
                    "Crush tomatoes by hand and spread over the dough, leaving a 1-inch border.",
                    "Tear mozzarella into pieces and distribute evenly.",
                    "Bake for 10–12 minutes until the crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil."
                ],
                Ratings = [5, 4, 5, 5, 4]
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, pecorino, guanciale, and black pepper.",
                Ingredients = ["Spaghetti (400g)", "Guanciale (200g)", "Egg yolks (6)", "Pecorino Romano (100g)", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Cut guanciale into strips and cook in a dry pan until crispy.",
                    "Whisk egg yolks with grated pecorino and plenty of black pepper.",
                    "Drain pasta, reserving 1 cup of pasta water.",
                    "Toss hot pasta with guanciale, then remove from heat and stir in egg mixture.",
                    "Add pasta water a splash at a time until creamy. Serve immediately."
                ],
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast (500g)", "Yogurt (1 cup)", "Garam masala", "Cumin", "Turmeric", "Tomato sauce (400ml)", "Heavy cream (1/2 cup)", "Onion", "Garlic", "Ginger"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, cumin, and turmeric for at least 1 hour.",
                    "Grill or broil chicken until lightly charred.",
                    "Sauté onion, garlic, and ginger in butter until soft.",
                    "Add tomato sauce and spices; simmer 15 minutes.",
                    "Stir in cream and the cooked chicken. Simmer 10 more minutes.",
                    "Serve over basmati rice with naan bread."
                ],
                Ratings = [5, 4, 4, 5]
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Description = "A vibrant stir-fried noodle dish packed with vegetables and a tangy sauce.",
                Ingredients = ["Rice noodles (200g)", "Tofu (200g)", "Bean sprouts", "Carrots", "Green onions", "Peanuts", "Lime", "Tamarind paste", "Fish sauce", "Brown sugar", "Eggs (2)"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes, then drain.",
                    "Mix tamarind paste, fish sauce, and brown sugar into a sauce.",
                    "Press and cube tofu; pan-fry until golden.",
                    "Scramble eggs in the same pan, then add julienned carrots.",
                    "Add noodles and sauce; toss until noodles are tender and coated.",
                    "Top with bean sprouts, crushed peanuts, green onions, and lime wedges."
                ],
                Ratings = [4, 5, 4]
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef (500g)", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa", "Lime"],
                Steps = [
                    "Brown ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water; simmer until thickened.",
                    "Warm tortillas in a dry pan or microwave.",
                    "Shred lettuce, dice tomato, and grate cheese.",
                    "Assemble tacos with beef and desired toppings.",
                    "Squeeze lime over the top and serve with salsa."
                ],
                Ratings = [4, 4, 5, 4, 3]
            },
            new Recipe
            {
                Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Individual cakes with a warm, molten chocolate center.",
                Ingredients = ["Dark chocolate (200g)", "Butter (120g)", "Eggs (4)", "Sugar (100g)", "Flour (60g)", "Vanilla extract"],
                Steps = [
                    "Preheat oven to 425°F (220°C). Butter and flour four ramekins.",
                    "Melt chocolate and butter together; let cool slightly.",
                    "Whisk eggs and sugar until thick and pale.",
                    "Fold chocolate mixture into eggs, then fold in flour and vanilla.",
                    "Divide among ramekins and bake 12–14 minutes until edges are firm but center jiggles.",
                    "Let stand 1 minute, then invert onto plates. Serve immediately."
                ],
                Ratings = [5, 5, 5, 4]
            }
        ];
        _nextId = 7;
    }

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

