using RecipeShare.Components;
using RecipeShare.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<RecipeService>();
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

@page "/"
@inject RecipeService RecipeService

<PageTitle>RecipeShare — Home</PageTitle>

<h1>🍽️ Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h4 class="card-title">
                        <span class="me-2">@CategoryIcon(category)</span>@category
                    </h4>
                    <p class="text-muted">@RecipeService.GetByCategory(category).Count recipe(s)</p>
                    <a href="category/@category" class="btn btn-outline-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mt-5">Latest Recipes</h2>
<div class="row mt-3">
    @foreach (var recipe in RecipeService.GetAll().TakeLast(3).Reverse())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <span class="badge bg-secondary mb-2">@recipe.Category</span>
                    <p class="card-text">@recipe.Description</p>
                    <div class="text-warning mb-2">
                        @for (int i = 1; i <= 5; i++)
                        {
                            <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                        }
                        <small class="text-muted ms-1">(@recipe.RatingCount)</small>
                    </div>
                    <a href="recipe/@recipe.Id" class="btn btn-sm btn-primary">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryIcon(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Thai" => "🇹🇭",
        "Mexican" => "🇲🇽",
        "Desserts" => "🍰",
        _ => "🍴"
    };
}

