}

@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star-rating @(star <= (selectedRating ?? 0) ? "selected" : "") @(star <= displayRating ? "highlighted" : "")"
              role="button"
              @onclick="() => Rate(star)"
              @onmouseover="() => displayRating = star"
              @onmouseout="() => displayRating = selectedRating ?? 0"
              style="font-size: 1.5rem; cursor: pointer; color: @(star <= displayRating ? "#ffc107" : "#ddd"); transition: color 0.15s;">
            ★
        </span>
    }
    @if (submitted)
    {
        <span class="ms-2 text-success fw-bold">Thanks!</span>
    }
    <small class="ms-2 text-muted">
        @if (recipe is not null)
        {
            @($"{recipe.AverageRating:F1} avg ({recipe.RatingCount} ratings)")
        }
    </small>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private Recipe? recipe;
    private int? selectedRating;
    private int displayRating;
    private bool submitted;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(RecipeId);
    }

    private void Rate(int rating)
    {
        selectedRating = rating;
        displayRating = rating;
        RecipeService.AddRating(RecipeId, rating);
        recipe = RecipeService.GetById(RecipeId);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (!string.IsNullOrEmpty(successMessage))
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="mt-3">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="model.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="model.Category" class="form-select">
            <option value="">— Select a category —</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Thai">Thai</option>
            <option value="Mexican">Mexican</option>
            <option value="Desserts">Desserts</option>
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="description" class="form-label">Short Description</label>
        <InputTextArea id="description" @bind-Value="model.Description" class="form-control" rows="2" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <small class="text-muted d-block mb-1">One ingredient per line</small>
        <InputTextArea id="ingredients" @bind-Value="model.IngredientsText" class="form-control" rows="5"
                       placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => model.IngredientsText" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <small class="text-muted d-block mb-1">One step per line</small>
        <InputTextArea id="steps" @bind-Value="model.StepsText" class="form-control" rows="5"
                       placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients and stir." />
        <ValidationMessage For="() => model.StepsText" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">
        Submit Recipe
    </button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        var ingredients = model.IngredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();
        var steps = model.StepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var recipe = RecipeService.AddRecipe(
            model.Title,
            model.Category,
            model.Description ?? string.Empty,
            ingredients,
            steps);

        successMessage = $"\"{recipe.Title}\" submitted successfully!";
        model = new();
    }

    private sealed class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        public string? Description { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Add at least one ingredient.")]
        public string IngredientsText { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Add at least one step.")]
        public string StepsText { get; set; } = string.Empty;
    }
}

